package dev.hrutvik.billing.outbox;
import org.apache.kafka.clients.producer.ProducerRecord; import org.springframework.beans.factory.annotation.Value; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import java.nio.charset.StandardCharsets; import java.time.Duration; import java.util.UUID; import java.util.concurrent.TimeUnit;
@Component
public class OutboxRelay {
 private final OutboxLeaseService leases; private final KafkaTemplate<String,String> kafka; private final String owner=UUID.randomUUID().toString(); private final int batchSize; private final Duration leaseDuration; private final Duration sendTimeout; private final String topic;
 public OutboxRelay(OutboxLeaseService leases,KafkaTemplate<String,String> kafka,@Value("${billing.outbox.batch-size:100}") int batchSize,@Value("${billing.outbox.lease-duration:PT30S}") Duration leaseDuration,@Value("${billing.outbox.send-timeout:PT5S}") Duration sendTimeout,@Value("${billing.outbox.topic:billing.usage-recorded.v1}") String topic){this.leases=leases;this.kafka=kafka;this.batchSize=batchSize;this.leaseDuration=leaseDuration;this.sendTimeout=sendTimeout;this.topic=topic;}
 @Scheduled(fixedDelayString="${billing.outbox.poll-delay:1000}") public void publishBatch(){for(var event:leases.claim(owner,batchSize,leaseDuration))publish(event);}
 void publish(OutboxEvent event){try{String destination=event.getDestination()==null||event.getDestination().isBlank()?topic:event.getDestination();var record=new ProducerRecord<String,String>(destination,event.getTenantId()+":"+event.getAggregateId(),event.getPayload());record.headers().add("event-id",event.getId().toString().getBytes(StandardCharsets.UTF_8));record.headers().add("event-type",event.getEventType().getBytes(StandardCharsets.UTF_8));record.headers().add("tenant-id",event.getTenantId().getBytes(StandardCharsets.UTF_8));kafka.send(record).get(sendTimeout.toMillis(),TimeUnit.MILLISECONDS);leases.markPublished(event.getId());}catch(Exception failure){leases.release(event.getId());}}
}
